 import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  vec4,
  mix,
  smoothstep,
  fract,
  sin,
  dot,
  uniform,
  texture,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const cBottomVal = new Color(colors.surface || '#0b0b10');
  const cTopVal = new Color(colors.ink || '#16161d');
  const cAccentVal = new Color(colors.accent || '#ff2a38');
  const cPaperVal = new Color(colors.paper || '#e8ecf2');

  const root = new Group();
  const content = new Group();
  root.add(content);

  // engineered gradient surface with subtle grain
  const uFade = uniform(0.0);
  const cBottom = uniform(cBottomVal);
  const cTop = uniform(cTopVal);
  const gradientT = smoothstep(0.0, 1.0, uv().y);
  const gradient = mix(cBottom, cTop, gradientT);

  const grainUV = uv().mul(2048.0);
  const grainNoise = fract(
    sin(dot(grainUV, vec2(12.9898, 78.233))).mul(43758.5453)
  );
  const grain = mix(gradient, vec3(grainNoise), 0.03);
  const bg = mix(vec3(0.0), grain, uFade);

  const surfaceGeo = new PlaneGeometry(5.2, 1.4);
  const surfaceMat = new MeshBasicNodeMaterial({ colorNode: vec4(bg, 1.0) });
  const surface = new Mesh(surfaceGeo, surfaceMat);
  surface.position.z = -0.08;
  content.add(surface);

  // accent rule
  const accentGeo = new PlaneGeometry(1.8, 0.04);
  const accentMat = new MeshBasicNodeMaterial({
    colorNode: vec4(cAccentVal, 1.0),
  });
  const accent = new Mesh(accentGeo, accentMat);
  accent.position.set(0, -0.34, 0.06);
  content.add(accent);

  // headline
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const item = items.find((i) => i.role === 'headline') || items[0] || { text: 'Pricing', typography: { fontSize: 96 } };
  const textObj = ctx.fontAtlas.createText(item.text, {
    fontSize: item.typography?.fontSize ?? 96,
    color: '#' + cPaperVal.getHexString(),
    align: 'center',
  });
  textObj.position.set(0, 0.04, 0.05);
  content.add(textObj);

  const disposables = [surfaceGeo, surfaceMat, accentGeo, accentMat];
  const textures = [];
  const timelines = [];
  let cleaned = false;

  // watermark the provided hero image behind the title
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        if (cleaned) {
          tex.dispose();
          return;
        }
        textures.push(tex);

        const aspect =
          tex.image?.width && tex.image?.height
            ? tex.image.width / tex.image.height
            : 1;

        const h = 2.4;
        const w = h * aspect;
        const wmGeo = new PlaneGeometry(1, 1);
        const texNode = texture(tex, uv());
        const wmColor = vec4(texNode.rgb, texNode.a.mul(0.12));

        const wmMat = new MeshBasicNodeMaterial({
          colorNode: wmColor,
          transparent: true,
          depthWrite: false,
        });

        const wm = new Mesh(wmGeo, wmMat);
        wm.scale.set(w, h, 1);
        wm.position.z = -0.04;
        content.add(wm);

        disposables.push(wmGeo, wmMat);
      })
      .catch(() => {});
  }

  // entrance
  const entrance = gsap.timeline();
  timelines.push(entrance);
  entrance.from(
    content.position,
    { y: 0.35, duration: 0.75, ease: 'power3.out' },
    0
  );
  entrance.from(
    content.scale,
    { x: 0.92, y: 0.92, duration: 0.85, ease: 'power4.out' },
    0
  );
  entrance.to(
    uFade,
    { value: 1, duration: 0.65, ease: 'power2.out' },
    0
  );

  // subtle idle breathing
  const idle = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.9 });
  timelines.push(idle);
  idle.to(content.scale, {
    x: 1.01,
    y: 1.01,
    duration: 3.2,
    ease: 'sine.inOut',
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    cleaned = true;
    for (const t of timelines) {
      try {
        t.kill();
      } catch (e) {}
    }
    for (const tx of textures) {
      try {
        tx.dispose();
      } catch (e) {}
    }
    for (const d of disposables) {
      try {
        if (d && d.dispose) d.dispose();
      } catch (e) {}
    }
    content.traverse((o) => {
      try {
        if (o.geometry) o.geometry.dispose();
        if (o.material && o.material.dispose) o.material.dispose();
      } catch (e) {}
    });
  };

  return root;
}
